function g(a){const t=new Date(a),n=t.getFullYear(),e=(t.getMonth()+1).toString().padStart(2,"0"),o=t.getDate().toString().padStart(2,"0");return`${n}-${e}-${o}`}function c(a){const t=new Date(a),n=t.getFullYear(),e=(t.getMonth()+1).toString().padStart(2,"0"),o=t.getDate().toString().padStart(2,"0"),r=t.getHours().toString().padStart(2,"0"),s=t.getMinutes().toString().padStart(2,"0");return`${n}年${e}月${o}日 ${r}:${s}`}export{c as a,g as f};
